// connectTimeout 啟動時主庫與副本 ping 的逾時。先前用不帶期限的 Ping()：資料庫主機不回應
// （封包被丟棄而非連線被拒）時，啟動會卡到作業系統的 TCP 連線逾時（Linux 約 2 分鐘；
// lib/pq 的 connect_timeout 預設 0 為無限等待）。變數而非常數，供測試縮短
var connectTimeout = 10 * time.Second

// pingWithTimeout 在 connectTimeout 內 ping 一次
func pingWithTimeout(db *sql.DB) error {
	ctx, cancel := context.WithTimeout(context.Background(), connectTimeout)
	defer cancel()
	return db.PingContext(ctx)
}

// Dialect SQL 方言介面（類似 bun 的 dialect 模式）
// 由 hidb/mysql 和 hidb/pg 子套件實現
type Dialect interface {
	DriverName() string         // sql.Open 使用的驅動名稱（"mysql" / "postgres"）
	BunDialect() schema.Dialect // bun ORM 使用的方言實例
}

// RedisDriver Redis 協議驅動介面（與 Dialect 同規格）
// 由 hidb/redis 子套件實現；KeyDB 兼容 Redis 協議，同樣適用。
// 子套件只負責驅動身分與 client 建構，連線參數組裝、ping 驗證、
// 資源追蹤 hook 由 core 的 initRedis 統一處理（對稱 initSQL）
// DSNChecker 由方言選擇性實作：檢查 DSN 裡常見的設定疏漏，回傳要提示的訊息（不擋啟動）
type DSNChecker interface {
	CheckDSN(dsn string) []string
}

type RedisDriver interface {
	Name() string                               // 驅動名稱（"redis"）
	NewClient(opt *redis.Options) *redis.Client // 建立 client
}

// Option 設定選項（functional options 模式）
type Option func(*Database)

// WithDialect 設定 SQL 方言
func WithDialect(d Dialect) Option {
	return func(db *Database) {
		db.dialect = d
	}
}

// WithRedis 設定 Redis 驅動（與 WithDialect 同規格）
// 可與 WithDialect 並用：SQL 主庫 + Redis 快取同時初始化
func WithRedis(d RedisDriver) Option {
	return func(db *Database) {
		db.redisDriver = d
	}
}

// Database 數據庫管理器
type Database struct {
	config      config.DatabaseConfigInterface
	dialect     Dialect     // SQL 方言（由 WithDialect 設定）
	redisDriver RedisDriver // Redis 驅動（由 WithRedis 設定）
	sqlDB       *sql.DB     // 主庫（寫入）
	hypDB       *bun.DB     // 主庫 HypDB ORM 實例（寫入）
	redisDB     *redis.Client

	// 讀寫分離
	replicaPool *ReplicaPool // 讀取副本池
	// readDB 為 ReadHypDB 回傳的實例：連的是主庫，另以 readResolver 把唯讀查詢分到健康的副本。
	// 沒有副本時就是 hypDB。它與 hypDB、各副本共用 bunDialect（model 註冊表）與查詢 hook
	readDB     *bun.DB
	bunDialect schema.Dialect

	over   overrides      // Option 指定的值
	set    settings       // 解析後的行為設定
	log    *logger.Logger // 慢查詢、副本狀態、設定提示
	recent recentWrites   // 跨請求的寫後讀
}

// NewWithInterface 使用接口創建數據庫實例
func NewWithInterface(cfg config.DatabaseConfigInterface, opts ...Option) (*Database, error) {
	if cfg == nil {
		return nil, fmt.Errorf("database config is nil")
	}

	db := &Database{config: cfg}

	// 應用選項
	for _, opt := range opts {
		opt(db)
	}

	db.resolveSettings()

	driver := cfg.GetDriver()
	if driver == "" {
		// 給了 WithDialect / WithRedis 卻沒有 driver：先前照樣回傳沒有任何連線的實例，
		// HypDB() 是 nil，要到第一個查詢才 nil pointer
		if db.dialect != nil || db.redisDriver != nil {
			return nil, fmt.Errorf("database.driver is empty but WithDialect / WithRedis was given; set database.driver (and dsn) in the config")
		}
		// 允許沒有數據庫配置
		return db, nil
	}

	// SQL 主庫（WithDialect 設定時）
	if db.dialect != nil {
		if _, err := db.initSQL(); err != nil {
			return nil, err
		}
	}

	// Redis（WithRedis 設定時；可與 SQL 並存，driver=redis 為 redis-only）
	if db.redisDriver != nil {
		if _, err := db.initRedis(); err != nil {
			// SQL 已初始化時一併關閉，避免半初始化狀態洩漏連線
			if db.hypDB != nil || db.sqlDB != nil {
				db.Close()
			}
			return nil, err
		}
	}

	if db.dialect != nil || db.redisDriver != nil {
		return db, nil
	}

	// Cassandra 不經過 hidb：以 cassandra.New 直接建立並自行 Close。
	// 先前的插件系統在建構時沒有任何插件可用（driver: cassandra 必定落到此錯誤），且全專案零使用，已移除
	if driver == "cassandra" {
		return nil, fmt.Errorf("driver cassandra is not managed by hidb; use cassandra.New from pkg/hidb/cassandra")
	}
	return nil, fmt.Errorf("unsupported database driver: %s (did you forget to use WithDialect / WithRedis?)", driver)
}

// initSQL 通用 SQL 數據庫初始化（使用 Dialect）
func (d *Database) initSQL() (*Database, error) {
	dsn := d.config.GetDSN()
	if dsn == "" {
		return nil, fmt.Errorf("%s DSN is required", d.dialect.DriverName())
	}

	db, err := sql.Open(d.dialect.DriverName(), dsn)
	if err != nil {
		return nil, fmt.Errorf("failed to open %s: %w", d.dialect.DriverName(), err)
	}

	if checker, ok := d.dialect.(DSNChecker); ok {
		for _, hint := range checker.CheckDSN(dsn) {
			d.log.Warning("database DSN", "hint", hint)
		}
	}

	d.tunePool(db, d.config.GetMaxIdleConns(), d.config.GetMaxOpenConns())

	// 測試連接
	if err := pingWithTimeout(db); err != nil {
		db.Close()
		return nil, fmt.Errorf("failed to ping %s: %w", d.dialect.DriverName(), err)
	}

	d.sqlDB = db
	d.bunDialect = d.dialect.BunDialect() // 只建立一次，主庫與副本共用（見 initReplica）
	d.hypDB = bun.NewDB(db, d.bunDialect, d.bunOptions()...)
	d.hypDB.AddQueryHook(queryHook{d})
	d.readDB = d.hypDB

	// 初始化讀取副本；失敗時一併關閉主庫：NewWithInterface 只回 error，
	// 呼叫端拿不到可 Close 的實例，先前主庫連線池就此洩漏
	if err := d.initReplicas(); err != nil {
		d.hypDB.Close()
		d.hypDB, d.readDB, d.sqlDB = nil, nil, nil
		return nil, err
	}
	if d.replicaPool != nil {
		d.readDB = bun.NewDB(db, d.bunDialect, append(d.bunOptions(), bun.WithConnResolver(readResolver{d}))...)
		d.readDB.AddQueryHook(queryHook{d})
	}

	return d, nil
}

// tunePool 套用連線池設定（主庫與副本共用）
func (d *Database) tunePool(db *sql.DB, maxIdle, maxOpen int) {
	if maxIdle > 0 {
		db.SetMaxIdleConns(maxIdle)
	}
	if maxOpen > 0 {
		db.SetMaxOpenConns(maxOpen)
	}
	// 連線定期回收，不讓長連線一直留著過期的狀態（預設 30 分鐘；database.conn_max_lifetime）
	db.SetConnMaxLifetime(d.set.connMaxLifetime)
	db.SetConnMaxIdleTime(d.set.connMaxIdleTime)
}

// initReplicas 初始化讀取副本（在主庫初始化後調用）
// 使用可選介面 ReplicaConfigProvider 進行型別斷言，保持向後兼容
func (d *Database) initReplicas() error {
	provider, ok := d.config.(config.ReplicaConfigProvider)
	if !ok {
		return nil // 配置不支持讀取副本，跳過
	}

	replicas := provider.GetReplicas()
	if len(replicas) == 0 {
		return nil // 無副本配置
	}

	if d.dialect == nil {
		return fmt.Errorf("dialect is required for read replicas")
	}

	d.replicaPool = NewReplicaPool()
	d.replicaPool.maxLag = d.set.maxReplicaLag
	d.replicaPool.prober, _ = d.dialect.(LagProber)
	d.replicaPool.notify = func(index int, up bool, reason string) {
		switch {
		case up && reason != "":
			d.log.Warning("read replica", "replica", index, "note", reason)
		case up:
			d.log.Info("read replica back in rotation", "replica", index)
		default:
			d.log.Warning("read replica removed from rotation", "replica", index, "err", reason)
		}
	}
	if d.set.maxReplicaLag > 0 && d.replicaPool.prober == nil {
		d.log.Warning("max_replica_lag is set but this dialect cannot measure replication lag; it is not enforced")
	}

	for i, replicaCfg := range replicas {
		replica, err := d.initReplica(replicaCfg)
		if err != nil {
			// 關閉已初始化的副本
			d.replicaPool.Close()
			d.replicaPool = nil
			return fmt.Errorf("failed to init read replica %d: %w", i, err)
		}
		replica.hypDB.AddQueryHook(queryHook{d})
		d.replicaPool.Add(replica)
	}

	// 被動健康剔除：背景探測，連續失敗的副本自動摘出輪詢
	// （否則 1/N 讀請求會持續打到死副本等逾時），恢復後自動加回
	d.replicaPool.StartHealthCheck()

	return nil
}

// initRedis 初始化 Redis 連接（對稱 initSQL：core 統一組裝連線
// 參數、掛 hook、ping 驗證；client 建構交給 RedisDriver）
func (d *Database) initRedis() (*Database, error) {
	redisConfig := d.config.GetRedisConfig()
	if redisConfig == nil {
		return nil, fmt.Errorf("Redis configuration is required")
	}

	addr := redisConfig.GetAddr()
	if addr == "" {
		addr = "localhost:6379"
	}

	opt := &redis.Options{
		Addr:     addr,
		Password: redisConfig.GetPassword(),
		DB:       redisConfig.GetDB(),
	}
	// 進階設定（ACL 使用者、TLS、連線池、逾時）：先前只有位址、密碼與 DB，
	// 需要 TLS 或 ACL 的託管 Redis 連不上
	if p, ok := redisConfig.(config.RedisOptionsProvider); ok {
		o := p.GetRedisOptions()
		opt.Username = o.Username
		opt.PoolSize = o.PoolSize
		opt.DialTimeout = time.Duration(o.DialTimeout) * time.Second
		opt.ReadTimeout = time.Duration(o.ReadTimeout) * time.Second
		opt.WriteTimeout = time.Duration(o.WriteTimeout) * time.Second
		if o.TLS {
			opt.TLSConfig = &tls.Config{MinVersion: tls.VersionTLS12}
		}
	}
	client := d.redisDriver.NewClient(opt)
	// 掛上資源追蹤 hook：每條命令自動累計操作數與觸及的 key 數量
	client.AddHook(redisResourceHook{})

	// 測試連接（有期限：先前用不帶期限的 context）
	ctx, cancel := context.WithTimeout(context.Background(), connectTimeout)
	defer cancel()
	if err := client.Ping(ctx).Err(); err != nil {
		client.Close()
		return nil, fmt.Errorf("failed to ping redis: %w", err)
	}

	d.redisDB = client

	return d, nil
}

// HypDB 獲取主庫的 HypDB ORM 數據庫實例（始終返回主庫，保持向後兼容）
// 如需讀寫分離，請使用 ReadHypDB() / WriteHypDB()
func (d *Database) HypDB() *bun.DB {
	return d.hypDB
}

// ReadHypDB 獲取讀取用的 HypDB ORM 實例。有讀取副本時，經由它執行的唯讀查詢輪詢健康的副本：
//   - 副本連不上時這次查詢改用下一個副本或主庫，並立刻把該副本移出輪詢
//   - 寫入後的讀取（同一個請求、或同一位使用者在 read_your_writes 時間內）與 UseMaster(ctx) 走主庫
//   - 經由它執行的寫入一律走主庫
//
// 沒有副本時就是主庫。回傳的是同一個實例，可以保存下來重複使用
func (d *Database) ReadHypDB() *bun.DB {
	if d.readDB != nil {
		return d.readDB
	}
	// 以下為不經 NewWithInterface 建立的 Database（測試）：直接取一個副本
	if d.replicaPool != nil {
		if db := d.replicaPool.Next(); db != nil {
			return db
		}
	}
	return d.hypDB
}

// WriteHypDB 獲取寫入用的 HypDB ORM 實例（始終返回主庫）
func (d *Database) WriteHypDB() *bun.DB {
	return d.hypDB
}

// Redis 獲取 Redis 客戶端
// 實際的 Redis 使用由掛在 client 上的 hook 計數（涵蓋此處取得的原始 client），不在存取點計數。
func (d *Database) Redis() *redis.Client {
	return d.redisDB
}

// SQL 獲取主庫的原始 SQL 數據庫連接（始終返回主庫，保持向後兼容）
// 如需讀寫分離，請使用 ReadSQL() / WriteSQL()
func (d *Database) SQL() *sql.DB {
	return d.sqlDB
}

// ReadSQL 獲取讀取用的原始 SQL 連接
// 如果有配置讀取副本，則從副本池中輪詢選擇；否則回退到主庫
func (d *Database) ReadSQL() *sql.DB {
	if d.replicaPool != nil {
		if db := d.replicaPool.NextSQL(); db != nil {
			return db
		}
	}
	return d.sqlDB
}

// WriteSQL 獲取寫入用的原始 SQL 連接（始終返回主庫）
func (d *Database) WriteSQL() *sql.DB {
	return d.sqlDB
}

// HasReplicas 檢查是否有配置讀取副本
func (d *Database) HasReplicas() bool {
	return d.replicaPool != nil && d.replicaPool.Len() > 0
}

// ReplicaCount 獲取讀取副本數量
func (d *Database) ReplicaCount() int {
	if d.replicaPool == nil {
		return 0
	}
	return d.replicaPool.Len()
}

// Close 關閉數據庫連接
// 注意：hypDB.Close() 會關閉底層 sql.DB（兩者一定同時設定），因此不需要重複關閉
// 關閉順序：讀取副本 → 主庫 → Redis
func (d *Database) Close() error {
	var errs []error

	// 先關閉讀取副本池
	if d.replicaPool != nil {
		if replicaErrs := d.replicaPool.Close(); len(replicaErrs) > 0 {
			errs = append(errs, replicaErrs...)
		}
		d.replicaPool = nil
	}

	// 關閉主庫 HypDB（會同時關閉底層 sql.DB）
	if d.hypDB != nil {
		if err := d.hypDB.Close(); err != nil {
			errs = append(errs, fmt.Errorf("failed to close HypDB database: %w", err))
		}
	}

	// 關閉 Redis 連接
	if d.redisDB != nil {
		if err := d.redisDB.Close(); err != nil {
			errs = append(errs, fmt.Errorf("failed to close Redis: %w", err))
		}
	}

	if len(errs) > 0 {
		return fmt.Errorf("errors closing database connections: %v", errs)
	}

	return nil
}

// ReplicaStatus 回傳每個讀取副本目前的狀態（是否在輪詢內、複寫延遲、最近的錯誤）；沒有副本時為 nil
func (d *Database) ReplicaStatus() []ReplicaStatus {
	if d.replicaPool == nil {
		return nil
	}
	return d.replicaPool.Status()
}

// IsConnected 檢查數據庫是否已連接（最多等 connectTimeout；先前主庫不回應時永遠不返回）
func (d *Database) IsConnected() bool {
	ctx, cancel := context.WithTimeout(context.Background(), connectTimeout)
	defer cancel()

	if d.sqlDB != nil {
		return d.sqlDB.PingContext(ctx) == nil
	}
	if d.redisDB != nil {
		return d.redisDB.Ping(ctx).Err() == nil
	}
	return false
}

// Type 獲取數據庫類型
func (d *Database) Type() string {
	if d.config != nil {
		return d.config.GetDriver()
	}
	return ""
}

// withRetry 執行 run；遇到死結 / 序列化失敗時重試（最多 tx_retries 次，預設 1）。
// 這類錯誤是資料庫要求「請重做一次」，整個交易已回滾。其餘錯誤不重試
func (d *Database) withRetry(ctx context.Context, run func() error) error {
	for attempt := 0; ; attempt++ {
		err := run()
		if err == nil || attempt >= d.set.txRetries || !errors.Is(Classify(err), ErrDeadlock) || ctx.Err() != nil {
			return err
		}
		time.Sleep(time.Duration(attempt+1) * 10 * time.Millisecond)
	}
}

// Transaction 執行事務（僅支持 SQL 數據庫，使用原始 sql.Tx）
// 接受任何 context.Context，包括 HypGo *context.Context（因其實現 context.Context 介面）。
// 遇到死結 / 序列化失敗時 fn 會被重新執行（見 WithTxRetries）
func (d *Database) Transaction(ctx context.Context, fn func(*sql.Tx) error) error {
	if d.sqlDB == nil {
		return fmt.Errorf("no SQL database connection")
	}
	if ctx == nil {
		ctx = context.Background()
	}
	resource.MarkDB()
	err := d.withRetry(ctx, func() error { return d.runTx(ctx, fn) })
	if err == nil {
		d.markWrite(ctx) // 原始 sql.Tx 不經過查詢 hook
	}
	return err
}

func (d *Database) runTx(ctx context.Context, fn func(*sql.Tx) error) error {
	tx, err := d.sqlDB.BeginTx(ctx, nil)
	if err != nil {
		return fmt.Errorf("failed to begin transaction: %w", err)
	}

	defer func() {
		if p := recover(); p != nil {
			tx.Rollback()
			panic(p)
		}
	}()

	if err := fn(tx); err != nil {
		if rbErr := tx.Rollback(); rbErr != nil {
			return fmt.Errorf("transaction failed: %v, rollback failed: %w", err, rbErr)
		}
		return err
	}

	if err := tx.Commit(); err != nil {
		return fmt.Errorf("failed to commit transaction: %w", err)
	}

	return nil
}

// HypDBTransaction 使用 HypDB ORM 執行事務
// 透過 bun.Tx 提供完整的 ORM 查詢能力
// 接受任何 context.Context，包括 HypGo *context.Context。
// 遇到死結 / 序列化失敗時 fn 會被重新執行（見 WithTxRetries）
func (d *Database) HypDBTransaction(ctx context.Context, fn func(context.Context, bun.Tx) error) error {
	if d.hypDB == nil {
		return fmt.Errorf("no HypDB database connection")
	}

	if ctx == nil {
		ctx = context.Background()
	}

	return d.withRetry(ctx, func() error { return d.hypDB.RunInTx(ctx, nil, fn) })
}

// HealthCheck 健康檢查：主庫與 Redis。讀取副本不算在內——副本掛掉時讀取會改走其他副本或主庫，
// 服務仍然正常；先前一個副本不通就回錯，接到 /health 會讓編排系統把健康的實例重啟。
// 副本的狀態見 ReplicaStatus。
// 接受任何 context.Context，包括 HypGo *context.Context
func (d *Database) HealthCheck(ctx context.Context) error {
	if ctx == nil {
		ctx = context.Background()
	}

	// 檢查主庫
	if d.sqlDB != nil {
		if err := d.sqlDB.PingContext(ctx); err != nil {
			return fmt.Errorf("SQL database unhealthy: %w", err)
		}
	}

	// 檢查 Redis
	if d.redisDB != nil {
		if err := d.redisDB.Ping(ctx).Err(); err != nil {
			return fmt.Errorf("Redis unhealthy: %w", err)
		}
	}

	return nil
}
